import{createHash}from"node:crypto";export function buildGovernanceReceiptBundle({receipts,proofs}){if(!receipts.length||receipts.length!==proofs.length||proofs.some(x=>!x.passed))throw Error("bundle invalid");let rs=[...receipts].sort((a,b)=>a.receiptHash.localeCompare(b.receiptHash)),ps=[...proofs].sort((a,b)=>a.proofHash.localeCompare(b.proofHash));let b={kind:"governance-receipt-bundle/v1",receipts:Object.freeze(rs),proofs:Object.freeze(ps)};return Object.freeze({...b,bundleHash:createHash("sha256").update(JSON.stringify(b)).digest("hex")})}
